import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.C2TvIV46.js";const p=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"megacrow/settings.md","filePath":"megacrow/settings.md"}'),i={name:"megacrow/settings.md"};function l(s,e,n,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Open <strong>Settings</strong> from the toolbar. Options are split into <strong>Compiler</strong> and <strong>Editor</strong> sections. Changes apply immediately and are remembered between sessions.</p><h2 id="compiler-settings" tabindex="-1">Compiler settings <a class="header-anchor" href="#compiler-settings" aria-label="Permalink to &quot;Compiler settings&quot;">​</a></h2><h3 id="gametype-author" tabindex="-1">Gametype Author <a class="header-anchor" href="#gametype-author" aria-label="Permalink to &quot;Gametype Author&quot;">​</a></h3><p>Creator name written into the compiled gametype metadata.</p><table tabindex="0"><thead><tr><th>Detail</th><th>Value</th></tr></thead><tbody><tr><td>Maximum length</td><td>16 characters</td></tr><tr><td>Default</td><td>Empty</td></tr></tbody></table><p>Leave empty if you do not want an author stamped into the file. This is separate from Discord or OS account names.</p><h3 id="compiler-profile" tabindex="-1">Compiler profile <a class="header-anchor" href="#compiler-profile" aria-label="Permalink to &quot;Compiler profile&quot;">​</a></h3><p>Controls which language extensions the compiler and language service allow.</p><table tabindex="0"><thead><tr><th>Profile</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>MegaloEvolved</strong> (default)</td><td>Enables MegaloEvolved product extensions on top of stock Megalo</td></tr><tr><td><strong>MegaloEdit</strong></td><td>Matches stock MegaloEdit — MegaloEvolved-only language extensions are disabled</td></tr></tbody></table><p>Use <strong>MegaloEdit</strong> when you need scripts and tooling behavior closer to the HREK MegaloEdit compiler.</p><h3 id="strict-compiler" tabindex="-1">Strict compiler <a class="header-anchor" href="#strict-compiler" aria-label="Permalink to &quot;Strict compiler&quot;">​</a></h3><p>When enabled, the compiler <strong>enforces localization</strong>:</p><ul><li>Quoted string literals in places that expect string-table symbols become <strong>errors</strong> (instead of warnings)</li><li>Missing <a href="/MegaloEvolved/beta/docs/language/elements/localized-include"><code>localized_include</code></a> files are treated more strictly (aligned with strict localization rules)</li></ul><p>When disabled (default), behavior is closer to permissive MegaloEdit-style compiles: literals may warn, and some localization gaps are softer.</p><p>For the full Megalo compiler switch model (including temporary overflow and HREK background), see <a href="/MegaloEvolved/beta/docs/language/compiler-settings">Compiler settings</a> in the language docs. The IDE toggle maps to the localization / string-literal strictness side of that model.</p><h2 id="editor-settings" tabindex="-1">Editor settings <a class="header-anchor" href="#editor-settings" aria-label="Permalink to &quot;Editor settings&quot;">​</a></h2><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><p>Language for the IDE chrome, diagnostics, and hover help.</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>English</strong></td><td>Default UI and messages</td></tr><tr><td><strong>日本語</strong></td><td>Japanese UI and compiler/IDE messages</td></tr></tbody></table><p>This also affects which string-table language is preferred when displaying compiled gametype name and description in the sidebar.</p><h3 id="editor-theme" tabindex="-1">Editor theme <a class="header-anchor" href="#editor-theme" aria-label="Permalink to &quot;Editor theme&quot;">​</a></h3><p>Color theme for the Megalo (Monaco) editor only — not the rest of the IDE chrome.</p><p>Available themes include MegaloEvolved Dark, VS Dark, Clouds Midnight, Cobalt2, Dracula, GitHub Dark / Light, Monokai, Night Owl, Nord, Oceanic Next, Solarized Dark / Light, Tomorrow Night, and Twilight.</p><h3 id="discord-rich-presence" tabindex="-1">Discord rich presence <a class="header-anchor" href="#discord-rich-presence" aria-label="Permalink to &quot;Discord rich presence&quot;">​</a></h3><p>When enabled, Discord can show that you are editing in MegaloEvolved (for example the current file). Turn off if you do not want editing activity shared on Discord.</p><table tabindex="0"><thead><tr><th>Default</th><th>On</th></tr></thead></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/megacrow/workspaces">Workspaces</a> — scripts and output folders (desktop)</li><li><a href="/MegaloEvolved/beta/docs/megacrow/export">Export</a> — compile output formats</li><li><a href="/MegaloEvolved/beta/docs/language/compiler-settings">Language compiler settings</a> — MegaloCompile switches in depth</li></ul>',29)])])}const m=t(i,[["render",l]]);export{p as __pageData,m as default};
